package pe.vichaval.gestionriego.riego.repository;import java.time.*;import org.springframework.data.jpa.repository.*;import pe.vichaval.gestionriego.riego.entity.TurnoRiego;public interface TurnoRiegoRepository extends JpaRepository<TurnoRiego,Long>{@Query("select count(t)>0 from TurnoRiego t where t.fecha=:f and t.horaInicio<:fin and t.horaFin>:ini")boolean hayCruce(LocalDate f,LocalTime ini,LocalTime fin);long countByFecha(LocalDate f);}